function num(v, d) { var n = Number(v); return isFinite(n) ? n : d; }
function z(v) { return Math.abs(v) < 0.005 ? 0 : v; }
function sgn(v, d) { var s = sdk.format(Math.abs(v), d); return (v > 0 ? '+' : (v < 0 ? '-' : '')) + s; }
export function evaluate({ inputs, time }) {
  var u = num(inputs && inputs.launchSpeed, 4);
  var g = num(inputs && inputs.gravity, 9.8);
  var tTop = u / g, tEnd = 2 * u / g;
  var t = sdk.clamp(num(time, 0), 0, tEnd);
  var eps = 1e-9;
  var apexHeight = u * u / (2 * g);
  var tossedHeight = Math.max(0, u * t - g * t * t / 2);
  var tossedVelocity = z(u - g * t);
  var tossedAcceleration = -g;
  var released = t >= tTop - eps;
  var dropHeight = released ? tossedHeight : apexHeight;
  var dropVelocity = released ? z(-g * Math.max(0, t - tTop)) : 0;
  var dropAcceleration = released ? -g : 0;
  var base = 330, ppm = 240 / 2.2;
  var yOf = function (h) { return base - h * ppm; };
  var vScale = 14, aScale = 5;
  var tossState, dropState;
  var tolTop = 0.005;
  if (t <= eps) tossState = 'At launch';
  else if (t >= tEnd - eps) tossState = 'At launch height';
  else if (Math.abs(t - tTop) < tolTop) tossState = 'At the top';
  else if (t < tTop) tossState = 'Rising';
  else tossState = 'Falling';
  if (!released) dropState = 'Held in place';
  else if (t >= tEnd - eps) dropState = 'At launch height';
  else if (t - tTop < 0.02) dropState = 'Just released';
  else dropState = 'Falling together';
  var objs = [];
  objs.push(sdk.axis('hAxis', { x: 62, y: base, length: 240, orientation: 'y', min: 0, max: 2.2, ticks: [0, 0.5, 1, 1.5, 2], label: 'Height', unit: 'm' }));
  var lanes = [
    { id: 'toss', x: 80, title: 'Toss', state: tossState, role: 'input', h: tossedHeight, v: tossedVelocity, a: tossedAcceleration },
    { id: 'drop', x: 360, title: 'Drop', state: dropState, role: 'prediction', h: dropHeight, v: dropVelocity, a: dropAcceleration }
  ];
  var apexY = yOf(apexHeight);
  for (var i = 0; i < lanes.length; i++) {
    var L = lanes[i];
    var bx = L.x + 85;
    objs.push.apply(objs, sdk.panel({ id: L.id + 'Lane', x: L.x, y: 30, w: 270, h: 380, title: L.title, state: L.state, role: L.role }));
    objs.push.apply(objs, sdk.groundMark(L.id + 'Launch', bx, base + 10, 60));
    if (released) {
      objs.push(sdk.circle(L.id + 'Outline', bx, apexY, 18, { role: 'neutral', opacity: 0.3 }));
    }
    var by = yOf(L.h);
    objs.push(sdk.circle(L.id + 'Ball', bx, by, 18, { role: L.role }));
    if (L.v !== 0) objs.push.apply(objs, sdk.vector(L.id + 'Vel', { x: bx - 22, y: by }, { value: Math.abs(L.v), direction: L.v > 0 ? 'up' : 'down' }, { scale: vScale, role: 'input' }));
    if (L.a !== 0) objs.push.apply(objs, sdk.vector(L.id + 'Acc', { x: bx + 22, y: by }, { value: Math.abs(L.a), direction: L.a > 0 ? 'up' : 'down' }, { scale: aScale, role: 'warning' }));
    objs.push.apply(objs, sdk.callout(L.x + 140, Math.min(by - 20, 290), ['v = ' + sgn(L.v, 2) + ' m/s', 'a = ' + sgn(L.a, 1) + ' m/s\u00b2'], { id: L.id + 'Call', role: L.role }));
    if (i === 1) {
      objs.push.apply(objs, sdk.gate('gate', bx, apexY + 11, { open: released, w: 36 }));
    }
  }
  var q = { launchSpeed: u, gravity: g, apexTime: tTop, apexHeight: apexHeight, tossedVelocity: tossedVelocity, tossedAcceleration: tossedAcceleration, tossedHeight: tossedHeight, dropVelocity: dropVelocity, dropAcceleration: dropAcceleration, dropHeight: dropHeight };
  return {
    frame: { width: 640, height: 420, objects: objs, readouts: [
      { id: 'tossedVelocity', value: tossedVelocity },
      { id: 'tossedAcceleration', value: tossedAcceleration },
      { id: 'dropVelocity', value: dropVelocity },
      { id: 'dropAcceleration', value: dropAcceleration }
    ] },
    quantities: q
  };
}
